// Draw jellyfish body
const centerX = 400;
const centerY = 400;
const bodyRadius = 40;

// Body with glowing effect
ctx.fillStyle = 'rgba(255, 255, 0, 0.7)';
ctx.beginPath();
ctx.arc(centerX, centerY, bodyRadius, 0, Math.PI * 2);
ctx.fill();

// Add some bubbles around jellyfish
ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
for(let i = 0; i < 15; i++) {
    const angle = (i / 15) * Math.PI * 2;
    const distance = 40 + i * 5;
    const x = centerX + Math.cos(angle) * distance;
    const y = centerY + Math.sin(angle) * distance;
    const radius = 3 + i * 0.5;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
}

// Add tentacles
const tentacleCount = 8;
for(let i = 0; i < tentacleCount; i++) {
    const angle = (i / tentacleCount) * Math.PI * 2 - Math.PI/2;
    const length = 60 + i * 5;
    const width = 5 + i * 1.5;

    // Tentacle body
    ctx.fillStyle = 'rgba(255, 200, 100, 0.8)';
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(
        centerX + Math.cos(angle) * length,
        centerY + Math.sin(angle) * length
    );

    // Tentacle tip
    ctx.lineTo(
        centerX + Math.cos(angle) * (length + 10),
        centerY + Math.sin(angle) * (length + 10)
    );

    ctx.lineWidth = width;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Tentacle shadow
    ctx.fillStyle = 'rgba(255, 150, 50, 0.4)';
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(
        centerX + Math.cos(angle) * length,
        centerY + Math.sin(angle) * length
    );
    ctx.lineTo(
        centerX + Math.cos(angle) * (length + 10),
        centerY + Math.sin(angle) * (length + 10)
    );
    ctx.fill();
}

// Add pulsating glow effect
const gradient = ctx.createRadialGradient(
    centerX, centerY, 0,
    centerX, centerY, bodyRadius * 2
);
gradient.addColorStop(0, 'rgba(255, 255, 0, 0.7)');
gradient.addColorStop(1, 'rgba(255, 255, 0, 0.1)');
ctx.fillStyle = gradient;
ctx.beginPath();
ctx.arc(centerX, centerY, bodyRadius * 1.5, 0, Math.PI * 2);
ctx.fill();

